insert into public.settings(key,value) values
 ('assets','{"logo":"","favicon":"","banner":"","og_image":""}'::jsonb),
 ('content','{"hero.eyebrow":"NEGIN KHODRO · TEHRAN","hero.title":"انتخابی فراتر از انتظار","hero.subtitle":"مقصدی برای یافتن خودروهای ممتاز؛ با مشاوره‌ای صادقانه، کارشناسی دقیق و تجربه‌ای آرام از نخستین بازدید تا لحظه تحویل.","hero.button":"مشاهده خودروهای موجود","hero.experience":"۱۵+","hero.deliveries":"۱۲۰۰","hero.satisfaction":"۹۸٪","featured.title":"منتخب نگین خودرو","featured.intro":"مدل‌هایی که از نگاه کارشناسان ما ارزش مکث کردن دارند.","selected.title":"پیشنهادهای ویژه","selected.intro":"گزیده‌ای از خودروهای آماده بازدید در شوروم.","categories.title":"از کجا شروع کنیم؟","categories.intro":"دسته‌بندی دلخواهتان را انتخاب کنید و گزینه‌ها را ببینید.","intro.title":"خرید خودرو، با اطمینان خاطر.","intro.body":"در نگین خودرو، انتخاب یک خودروی ممتاز فقط به دیدن چند تصویر و مقایسه قیمت خلاصه نمی‌شود. هر خودرو پیش از عرضه، با دقت بررسی می‌شود و مشاوران ما با شناخت نیاز شما، گزینه‌های مناسب را شفاف و بی‌اغراق معرفی می‌کنند.\nاز نخستین گفت‌وگو تا کارشناسی، هماهنگی بازدید و تحویل، در کنار شما هستیم؛ تا انتخاب نهایی دقیقاً همان چیزی باشد که می‌خواهید.","intro.experience":"۴ مرحله","intro.deliveries":"۳۶۰°","intro.satisfaction":"۱ همراه","contact.title":"برای انتخاب بعدی‌تان آماده‌اید؟","contact.body":"مشاوران نگین خودرو برای یک گفت‌وگوی کوتاه و بی‌تعهد در کنار شما هستند.","contact.inquiry_title":"درخواست مشاوره","contact.inquiry_intro":"اطلاعاتتان را ثبت کنید تا در اولین فرصت با شما تماس بگیریم.","guide.title":"راهنمای خرید خودرو","guide.intro":"یک انتخاب خوب با شناخت درست آغاز می‌شود. این راهنمای کوتاه کمک می‌کند با آمادگی بیشتر به سراغ خودروی بعدی‌تان بروید.","about.title":"درباره نگین خودرو","about.intro":"نگین خودرو برای کسانی ساخته شده که در انتخاب خودرو، به همان اندازه که به کیفیت اهمیت می‌دهند، به آرامش خاطر هم فکر می‌کنند.","about.experience":"۱۵ سال تجربه در انتخاب و کارشناسی خودروهای ممتاز.","about.deliveries":"همراهی دقیق از مشاوره اولیه تا تحویل خودرو.","about.satisfaction":"رضایت مشتری با شفافیت و پیگیری مسئولانه.","forms.name":"نام و نام خانوادگی","forms.phone":"شماره تماس","forms.message":"پیام شما","forms.submit":"ارسال درخواست"}'::jsonb)
